import React, { useState, useEffect } from "react";
import ReactMarkdown from "react-markdown";
import remarkMath from "remark-math";
import remarkGfm from "remark-gfm";
import rehypeKatex from "rehype-katex";
import rehypeRaw from "rehype-raw";
import "katex/dist/katex.min.css";
import "./BlogPost.css";
import "../colors.css";
import Header from "./Header";

const BlogPost = () => {
  const [content, setContent] = useState("");
  const [title, setTitle] = useState("");
  const [authors, setAuthors] = useState("");
  const [course, setCourse] = useState("");
  const [date, setDate] = useState("");

  useEffect(() => {
    const filePath = "/assets/blog/blog1/blog.md";

    fetch(filePath)
      .then((response) => response.text())
      .then((text) => {
        const lines = text.split("\n");
        let contentStartIndex = 0;

        lines.forEach((line, index) => {
          if (line.startsWith("Title:")) {
            setTitle(line.replace("Title:", "").trim());
            contentStartIndex = index + 1;
          } else if (line.startsWith("Authors:")) {
            setAuthors(line.replace("Authors:", "").trim());
            contentStartIndex = index + 1;
          } else if (line.startsWith("Course:")) {
            setCourse(line.replace("Course:", "").trim());
            contentStartIndex = index + 1;
          } else if (line.startsWith("Date:")) {
            setDate(line.replace("Date:", "").trim());
            contentStartIndex = index + 1;
          }
        });

        const body = lines.slice(contentStartIndex).join("\n");

        // Render numeric citations like [1,2] as clickable superscripts that jump to references
        const withLinkedCitations = body.replace(
          /\[([0-9,\s]+)\]/g,
          (match, nums) => {
            const links = nums
              .split(",")
              .map((n) => n.trim())
              .filter(Boolean)
              .map((n) => `<a href="#ref-${n}">[${n}]</a>`)
              .join(" ");
            return `<sup>${links}</sup>`;
          }
        );

        setContent(withLinkedCitations);
      })
      .catch((error) => console.error("Error loading blog post:", error));
  }, []);

  return (
    <>
      <Header />
      <div className="blog-post-container">
        <div className="blog-post-content">
          {title && (
            <div className="blog-post-header">
              <h1 className="blog-post-page-title">{title}</h1>
              {[authors, course, date].filter(Boolean).length > 0 && (
                <p className="blog-post-authors">
                  {[authors, course, date].filter(Boolean).map((part, idx) => (
                    <span className="blog-post-meta-item" key={idx}>
                      {part}
                    </span>
                  ))}
                </p>
              )}
            </div>
          )}
          <ReactMarkdown
            remarkPlugins={[remarkMath, remarkGfm]}
            rehypePlugins={[rehypeKatex, rehypeRaw]}
            components={{
              img: ({ node, ...props }) => (
                <div className="blog-post-image-container">
                  <img
                    {...props}
                    alt={props.alt || ""}
                    className="blog-post-image"
                  />
                </div>
              ),
            }}
          >
            {content}
          </ReactMarkdown>
        </div>
      </div>
    </>
  );
};

export default BlogPost;
